const qs = [
  ["proto/server", "rg -n \"CreateMemo|ListMemos|Transcribe|service .*Service|ShortcutService\" proto"],
  ["db", "rg -n \"type .*Driver|New.*Store|postgres|sqlite|mysql|CREATE TABLE.*memo|memo_relation|DELETE FROM\" store server"],
  ["frontend", "rg -n \"create.*Client|ListMemos|CreateMemo|use.*Memo|MemoService|Connect\" web frontend 2>/dev/null || true"],
  ["handlers", "rg -n \"func \\(.*\\).*\\(.*Memo|Store\\.CreateMemo|GetUser|Broadcast|webhook|Webhook|DeleteMemo\" server"],
];
const out = await Promise.all(qs.map(async ([n,cmd]) => {
  const r=await tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:8000}); return `===${n}===\n${r.output}`;
}));
out.forEach(text);

