"rg -n \"runner|Runner|Start\\(|scheduler|NewScheduler|memopayload|s3presign\" server --glob '*.go' | head -160",
"nl -ba server/router/api/v1/memo_service_webhooks.go; nl -ba internal/webhook/webhook.go | sed -n '1,180p'; rg -n \"Deliver|Dispatch\" internal server/router/api/v1 --glob '*.go'",
"nl -ba web/src/connect.ts | sed -n '1,170p'; nl -ba server/auth/token.go | sed -n '1,180p'; rg -n \"auth.*intercept|intercept.*auth|Validate|Parse.*Token\" web/src server/auth",
"nl -ba store/db/sqlite/memo.go | sed -n '225,280p'; nl -ba store/db/postgres/memo.go | sed -n '235,280p'; nl -ba store/db/mysql/memo.go | sed -n '250,300p'; rg -n \"memo_|CREATE TABLE.*memo|CREATE TABLE.*attachment|CREATE TABLE.*reaction\" store/migration/*/LATEST.sql | head -80",
"rg -n \"type (User|Attachment|Reaction) struct\" store/{user,attachment,reaction}.go; rg -n \"store\\.Memo|\\*Memo|Memo{\" --glob '*.go' --glob '!**/test/**' | cut -d: -f1 | sort -u"
];
